CREATE SCHEMA IF NOT EXISTS messaging;

CREATE TABLE IF NOT EXISTS messaging.sms (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    uuid TEXT NOT NULL,
    number TEXT NOT NULL,
    body TEXT NOT NULL,
    state sms_state NOT NULL DEFAULT 'outgoing',
    failure_type sms_failure_type,
    error_message TEXT,
    mail_message_id UUID,
    iap_status_code INTEGER,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS sms_state_idx ON messaging.sms (state);

CREATE UNIQUE INDEX IF NOT EXISTS idx_sms_uuid ON messaging.sms (uuid);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_sms_metadata_gin ON messaging.sms USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_sms_metadata_deleted_at ON messaging.sms ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_sms_metadata_created_at ON messaging.sms ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_sms_metadata_updated_at ON messaging.sms ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION messaging.sms_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS sms_insert_audit ON messaging.sms;
CREATE TRIGGER sms_insert_audit BEFORE INSERT ON messaging.sms
    FOR EACH ROW EXECUTE FUNCTION messaging.sms_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS sms_update_audit ON messaging.sms;
CREATE TRIGGER sms_update_audit BEFORE UPDATE ON messaging.sms
    FOR EACH ROW EXECUTE FUNCTION messaging.sms_audit_timestamp();
